    readonly 'integrationsCatalog.entry.linear.details': 'Verbind Linear zodat de agent je tickets leest, ze aanmaakt en bijwerkt, werk tussen cycli verplaatst en je rapporteert hoe projecten ervoor staan.';
    readonly 'integrationsCatalog.entry.atlassian.details': 'Verbind Atlassian zodat de agent Jira-tickets doorzoekt en leest, status en reacties bijwerkt en de Confluence-pagina’s vindt die je vraag beantwoorden.';
    readonly 'integrationsCatalog.entry.notion.details': 'Verbind Notion zodat de agent je workspace doorzoekt, pagina’s en databases leest en pagina-inhoud bewerkt als je daarom vraagt. Inclusief Notion-skills voor het vastleggen van kennis, onderzoek over pagina’s heen, het voorbereiden van vergaderingen en het omzetten van specs in taken.';
