    readonly 'integrationsCatalog.entry.gitlab.details': 'Verbind GitLab zodat de agent projecten en tickets leest, aan merge requests werkt en de pipeline-status van je groep controleert.';
    readonly 'integrationsCatalog.entry.figma.details': 'Verbind Figma zodat de agent je ontwerpbestanden leest, variabelen en styles ophaalt en de codeverbindingen volgt terwijl hij de UI bouwt.';
    readonly 'integrationsCatalog.entry.canva.description': 'Ontwerpen maken, bewerken en exporteren in Canva';
    readonly 'integrationsCatalog.entry.canva.details': 'Verbind Canva zodat de agent ontwerpen maakt vanuit een beschrijving, bestaande bewerkt, je ontwerpen en mappen doorzoekt, brand kits en sjablonen gebruikt en exporteert naar PDF, PNG of andere formaten.';
    readonly 'integrationsCatalog.entry.supabase.details': 'Verbind Supabase zodat de agent je projecten bekijkt, tabellen opvraagt en instelt en branches beheert als je daarom vraagt.';
    readonly 'integrationsCatalog.entry.neon.details': 'Verbind Neon zodat de agent je Postgres-branches en -databases opsomt en standaard alleen-lezen query’s draait. Inclusief de Neon Postgres-skill.';
    readonly 'integrationsCatalog.entry.stripe.details': 'Verbind Stripe zodat de agent betalingen, klanten en terugbetalingen opzoekt en de rekeningactiviteit in je testmodus uitlegt.';
    readonly 'integrationsCatalog.entry.cloudflare.details': 'Verbind Cloudflare zodat de agent DNS-records bekijkt, Workers uitrolt en beheert en opslag en accountinstellingen leest.';
    readonly 'integrationsCatalog.entry.vercel.details': 'Verbind Vercel zodat de agent je projecten uitrolt, deployments en logs bekijkt en domeinen en projectinstellingen beheert.';
    readonly 'integrationsCatalog.entry.sentry.details': 'Verbind Sentry zodat de agent recente fouten ophaalt, stack traces doorgrondt en de status van issues en releases volgt. Ook inclusief de Sentry-skill voor het debuggen en oplossen van een issue.';
    readonly 'integrationsCatalog.entry.huggingface.details': 'Verbind Hugging Face zodat de agent modellen, datasets en Spaces doorzoekt en hun details en gebruikstips ophaalt.';
    readonly 'integrationsCatalog.entry.aws.details': 'Verbind AWS zodat de agent resources zoals EC2, S3, Lambda en CloudWatch in jouw regio bekijkt en beheert.';
    readonly 'integrationsCatalog.entry.datadog.details': 'Verbind Datadog zodat de agent monitors, metrics, logs en incidenten opvraagt op de site die je kiest.';
    readonly 'integrationsCatalog.entry.dropbox.description': 'Bestanden in Dropbox vinden, lezen en delen';
