    readonly 'integrationsCatalog.entry.hex.description': 'Data bevragen en projecten draaien in Hex';
    readonly 'integrationsCatalog.entry.hex.details': 'Verbind Hex zodat de agent je projecten zoekt, ze uitvoert en Hex vragen stelt over de data waarmee je workspace verbonden is.';
    readonly 'integrationsCatalog.entry.clickup.description': 'Werken met ClickUp-taken, docs en spaces';
    readonly 'integrationsCatalog.entry.clickup.details': 'Verbind ClickUp zodat de agent taken vindt, maakt en bijwerkt, docs en reacties leest en werk door je spaces en lijsten verplaatst.';
    readonly 'integrationsCatalog.entry.shortcut.description': 'Werken met Shortcut-stories, epics en iteraties';
