    readonly 'integrationsCatalog.entry.miro.description': 'Miro-borden en diagrammen lezen en maken';
    readonly 'integrationsCatalog.entry.miro.details': 'Verbind Miro zodat de agent je borden leest, sticky notes en frames omzet in gestructureerde context en diagrammen en documenten op een bord maakt.';
