    readonly 'integrationsCatalog.entry.exa.description': 'Zoeken op het web en pagina’s lezen met Exa';
    readonly 'integrationsCatalog.entry.exa.details': 'Geef de agent webzoeken en pagina’s lezen via Exa, een zoekmachine voor AI-agents. Werkt zonder sleutel binnen de gratis limiet; voeg een API-sleutel toe voor meer. Inclusief Exa-skills voor bedrijfsonderzoek en het opbouwen van leadlijsten.';
