    readonly 'integrationsCatalog.entry.postman.details': 'Verbind Postman zodat de agent je collecties uitvoert, workspaces bekijkt en API-definities opzoekt.';
    readonly 'integrationsCatalog.entry.context7.details': 'Verbind Context7 zodat de agent actuele documentatie ophaalt voor exact de library-versie die je code gebruikt. Inclusief de Context7-skill die de agent vertelt wanneer hij documentatie moet opzoeken.';
    readonly 'integrationsCatalog.entry.microsoft-learn.details': 'Verbind Microsoft Learn zodat de agent in de officiële Microsoft-documentatie zoekt en zijn bevindingen aanhaalt.';
    readonly 'integrationsCatalog.entry.playwright.details': 'Installeer Playwright zodat de agent een echte browser opent, door pagina’s klikt, schermafbeeldingen maakt en controleert wat hij bouwt.';
