    readonly 'settings.magicPrompts.page.group.sessionWorkspaceReview.title': 'Werkruimtereview';
    readonly 'settings.magicPrompts.page.group.sessionExplore.title': 'Rondleiding door de codebase';
    readonly 'settings.magicPrompts.page.group.sessionExplore.description': 'Prompts die worden gebruikt door de slash-opdracht /explore: zichtbaar gebruikersbericht + verborgen instructies. Onderzoekt de repository en geeft een gestructureerde oriëntatie — het grote geheel, de belangrijkste modules, hoe ze samenhangen en waar u moet beginnen — in plaats van een opsomming per bestand.';
    readonly 'settings.magicPrompts.page.group.sessionWorkspaceReview.description': 'Prompts die worden gebruikt door de slash-opdracht /workspace-review: zichtbaar gebruikersbericht + verborgen instructies. Reviewt de diff van de werkruimte op bereiking van de bedoeling, juistheid en toereikendheid, waarbij bevindingen op ernst worden ingedeeld. De instructies gelden ook voor reviewsessies, inclusief de automatische reviewlus.';
    readonly 'settings.magicPrompts.page.group.sessionFeaturePlan.title': 'Functieplanning';
