    readonly 'settings.magicPrompts.page.group.sessionCatchUp.title': 'Inhalen';
    readonly 'settings.magicPrompts.page.group.sessionCatchUp.description': 'Prompts die de slash-opdracht /catch-up gebruikt: zichtbaar gebruikersbericht + verborgen instructies. Bouwt branchbewuste context — de commits van de branch, de bijbehorende PR en het ongecommitte werk samen — om te begrijpen waar u mee bezig was, en geeft daarna een overzichtelijke samenvatting en een volgende stap die op het product is gericht.';
    readonly 'settings.magicPrompts.page.group.sessionDebug.title': 'Debuggen';
    readonly 'settings.magicPrompts.page.group.sessionDebug.description': 'Prompts die de slash-opdracht /debug gebruikt: zichtbaar gebruikersbericht + verborgen instructies. Voert een begeleid onderzoek naar de grondoorzaak uit — legt het symptoom vast, stelt hypothesen op, toetst ze aan de code en bevestigt de oorzaak voordat er een oplossing wordt voorgesteld.';
    readonly 'settings.magicPrompts.page.group.sessionWeigh.title': 'Opties afwegen';
    readonly 'settings.magicPrompts.page.group.sessionWeigh.description': 'Prompts die de slash-opdracht /weigh gebruikt: zichtbaar gebruikersbericht + verborgen instructies. Onderzoekt de code en zet daarna 2-3 verschillende aanpakken uiteen met voor- en nadelen en een aanbeveling — zonder plan of code te schrijven.';
    readonly 'settings.magicPrompts.page.group.sessionFusion.title': 'Samenvoegen';
